764	/// Sends a DSR response for the current color scheme to the pty.
765	/// Record a Kitty clipboard protocol session grant so future requests
766	/// carrying the password skip the permission prompt.
767	pub fn kittyClipboardGrant(
768	    self: *Termio,
769	    pw: []const u8,
770	    dir: terminalpkg.kitty.clipboard.Grants.Direction,
771	) error{OutOfMemory}!void {
