165	/// The configuration for this IO that is derived from the main
166	/// configuration. This must be exported so that we don't need to
167	/// pass around Config pointers which makes memory management a pain.
168	/// Convert the vt-xt-checksum-extension config, whose values are named for
169	/// what they turn on, to the XTCHECKSUM bits, which turn things off.
170	fn xtChecksumFlags(
171	    ext: configpkg.Config.XtChecksumExtension,
172	) terminalpkg.xt_checksum.Flags {
173	    return .{
174	        .positive = !ext.negate,
175	        .no_attributes = !ext.attributes,
176	        .no_trim = !ext.trim,
177	        .undrawn = ext.undrawn,
178	        .full = ext.full,
179	    };
180	}
